CREATE COLUMN TABLE "TEST_AP"."OCPT" ("AbsEntry" INTEGER CS_INT NOT NULL , "Code" SMALLINT CS_INT NOT NULL , "Name" NVARCHAR(20) NOT NULL , "Descr" NVARCHAR(100), "IsDefault" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT NOT NULL , "IsPublic" NVARCHAR(1) DEFAULT 'N', "Strategy" NVARCHAR(20), "_Top" INTEGER CS_INT, "_Left" INTEGER CS_INT, "_Width" INTEGER CS_INT, "_Height" INTEGER CS_INT, "Date" LONGDATE CS_LONGDATE, "Time" SMALLINT CS_INT, "Mnfacturer" NVARCHAR(50), "Pubby" NVARCHAR(30), "Disabled" NVARCHAR(1) DEFAULT 'N', "Type" NVARCHAR(1) DEFAULT 'U', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCPT_CODE" ON "TEST_AP"."OCPT" ( "Code" ASC, "UserSign" ASC );
CREATE UNIQUE INDEX "OCPT_NAME" ON "TEST_AP"."OCPT" ( "Name" ASC, "UserSign" ASC )